it('aborts a request if the signal is aborted after the response headers have been read', async () => {
    const abortController = new AbortController()
    const scope = nock('http://example.test').post('/form').reply(201, 'OK!')

    const makeRequest = () =>
      new Promise((resolve, reject) => {
        http
          .request('http://example.test/form', {
            signal: abortController.signal,
            method: 'POST',
          })
          .on('response', res => {
            abortController.abort()
            res
              .on('data', () => {})
              .on('error', error => {
                reject(error)
              })
              .on('end', () =>
                resolve({
                  statusCode: res.statusCode,
                }),
              )
          })
          .on('error', error => {
            reject(error)
          })
          .end()
      })

    const error = await makeRequest().catch(error => error)
    expect(error).to.have.property('message', 'The operation was aborted')
    expect(error).to.have.property('name', 'AbortError')
    expect(error).to.have.property('code', 'ABORT_ERR')
    expect(error.cause).to.have.property(
      'message',
      'This operation was aborted',
    )
    scope.done()
  })

it('Emits the expected event sequence when aborted multiple times', done => {
    const scope = nock('http://example.test').get('/').reply()

    const req = http.request('http://example.test')
    const emitSpy = sinon.spy(req, 'emit')

    req.on('error', () => {}) // listen for error so it doesn't bubble
    req.on('socket', () => {
      req.abort()
      req.abort()
      req.abort()
    })
    req.end()

    setTimeout(() => {
      const events = emitSpy.args.map(i => i[0])
      // important: `abort` and `error` events only fire once and the `close` event still fires at the end
      expect(events).to.deep.equal(['socket', 'abort', 'error', 'close'])
      expect(scope.isDone()).to.be.false()
      done()
    }, 10)
  })

