        .reply(200, 'Hello World!', [
          'X-My-Header',
          'My Header value',
          'X-Other-Header',
          'My Other Value',
        ])

      const { headers, rawHeaders } = await got('http://example.test/')

      expect(headers).to.deep.equal({
