    nock('http://example.test')
      .post('/', Buffer.from([0xff, 0xff, 0xfa]))
      .reply(200)

    const request = got.post('http://example.test', {
      body: Buffer.from([0xff, 0xff, 0xff]),
    })

    await assertRejects(request, /Nock: No match for request/)
  })

